keys = ['name','url','category','evidence','price','delivery','payment','terms','lesson']
rows = []
for index, line in enumerate(DATA.strip().splitlines(), 1):
    values = line.split('|')
    assert len(values) == len(keys), (index, len(values))
    rows.append({'id': index, **dict(zip(keys,values)), 'checked_on': '2026-10-22'})
assert len(rows) == 50, len(rows)
assert len({x['url'] for x in rows}) == 50
(ROOT/'sites-50.json').write_text(json.dumps(rows, ensure_ascii=False, indent=2)+'\n')

intro = '''# AI 代充站：50 个站点的公开信息核验清单

核验日期：2026-10-22。用途：商业模式、产品流程和建站选型研究，不是采购推荐名单。

这里的“原站已读”只证明读到了经营者公开的商品/帮助/售后说明，不代表交易成功、渠道授权、主体真实或经营成熟。页面销量、成功率、卡来源、保障与删除凭证等说法均视为商家自述。价格是公开广告快照，不含未展示的通道费、税费、汇差，未实际下单。不同渠道、账号资格、时长、保障不能混作同一商品比较。X 交叉核验只确认经营者公开关联了相应入口。

50 是站点样本数，不是独立经营主体或独立上游数；相似品牌、共用模板或供应商不证明归属相同。待补核样本不能视为已经成熟运营。已把 PriceAI、AI代充比价、供货聚合、AIchongzhi 导购与纯兑换入口放在主报告另外讨论，没有混入这 50 个零售候选样本。
'''
md = [intro]
for x in rows:
    md += [f"## {x['id']:02d}. [{x['name']}]({x['url']})",f"类型：{x['category']}｜证据：{x['evidence']}｜核验日期：{x['checked_on']}",f"- **公开报价：** {x['price']}\n- **交付：** {x['delivery']}\n- **收款：** {x['payment']}\n- **售后与约束：** {x['terms']}\n- **研究判断：** {x['lesson']}"]
(ROOT/'50站点逐项调研.md').write_text('\n\n'.join(md)+'\n')
print(json.dumps({'count':len(rows),'evidence':{e:sum(x['evidence']==e for x in rows) for e in sorted({x['evidence'] for x in rows})}},ensure_ascii=False))
